<script setup lang="ts">
import { useToastMessage } from '../composables/useToast';
import { computed, ref } from 'vue';
import { api } from '../api/client';
import { chainLine, parseChainInput } from '../features/tools/chain';
const text = defineModel<string>({required:true});
const host = ref(location.hostname), port = ref('443'), name = ref('链式代理'), type = ref('socks5'), address = ref('');
const checked = ref(''), result = ref<Record<string, unknown> | null>(null), error = useToastMessage('error'), message = useToastMessage('success'), busy = ref(false);
const chainKey = computed(() => `${type.value}://${address.value.trim()}`);
async function run(action: () => Promise<void>) { busy.value = true; error.value = ''; message.value = ''; try { await action(); } catch (e) { error.value = e instanceof Error ? e.message : '请求失败'; } finally { busy.value = false; } }
function normalizeChainInput() { const value = parseChainInput(address.value, type.value); type.value = value.scheme; address.value = value.address; if (value.name) name.value = value.name; }
async function checkProxy() { normalizeChainInput(); const key = chainKey.value; checked.value = ''; result.value = null; await run(async () => { const value = await api<Record<string, unknown>>('/api/proxy-check', { type: type.value, address: address.value.trim().replace(new RegExp(`^${type.value}(?:://|=)`, 'i'), '') }); result.value = value; if (value.success === true && key === chainKey.value) { checked.value = key; message.value = '代理检测成功'; } else throw new Error(String(value.error || '检测失败，请重新验证')); }); }
async function append() { await run(async () => { if (checked.value !== chainKey.value) throw new Error('请先验证当前代理'); const line = chainLine(host.value, port.value, name.value, type.value, address.value); text.value = text.value.trim() ? `${text.value.trim()}\n${line}` : line; message.value = '已追加链式代理节点，请保存优选订阅'; }); }
</script><template><section class="subscription-helper"><h2>链式代理节点</h2><label for="chain-host">优选域名/IP</label><input id="chain-host" v-model="host" /><label for="chain-port">端口（可留空）</label><input id="chain-port" v-model="port" /><label for="chain-name">节点名称</label><input id="chain-name" v-model="name" /><label for="chain-type">代理协议</label><select v-glass-select id="chain-type" v-model="type"><option v-for="p in ['socks5','http','https','turn','sstp']" :key="p">{{ p }}</option></select><label for="chain-address">代理地址</label><input id="chain-address" v-model="address" type="password" autocomplete="off" placeholder="user:password@host:port" /><div class="actions"><button type="button" :disabled="busy" @click="checkProxy">检测代理</button><button type="button" :disabled="busy || checked !== chainKey" @click="append">追加地址库</button></div><dl v-if="result"><template v-for="key in ['ip','loc','responseTime']" :key="key"><dt>{{ key }}</dt><dd>{{ result[key] ?? '—' }}</dd></template></dl></section></template>
